  const geo = $('Get Coordinates').first().json;
  const geoItem = Array.isArray(geo) ? geo[0] : geo;
  const payload = {
    q: `${vars.query} in ${vars.location}`,
    gl: 'gb',
    hl: 'en'
  };
  if (geoItem && geoItem.lat && geoItem.lon) {
    payload.ll = `@${geoItem.lat},${geoItem.lon},13z`;
  }
  return JSON.stringify(payload);
})() }}

