/**
 * BULLETPROOF LEAD QUALIFIER & VERIFIER
 * 1. Eliminates corporate call centers (0800, 0845, 0870, 0300) so you only reach direct trade owners
 * 2. Normalizes phone numbers to standard UK format (+44...)
 * 3. Identifies UK mobiles (+447...) and generates 1-click WhatsApp links
 * 4. Accurately detects 'no_website' vs 'social_only' vs 'has_website'
 * 5. Deduplicates by phone and business name
 * 6. Generates custom cold outreach pitch
 */

const items = $input.all();
const config = $('Edit Fields').first().json || {};
const query = config.query || 'roofers';
const location = config.location || 'london';
const minReviews = Number(config.min_reviews || 1);
const onlyNoWebsite = Boolean(config.only_no_website === true);

function detectTrade(name, category, q) {
  const text = `${name || ''} ${category || ''} ${q || ''}`.toLowerCase();
  if (text.includes('roof')) return 'Roofer';
  if (text.includes('plumb') || text.includes('drain') || text.includes('heat') || text.includes('boiler')) return 'Plumber';
  if (text.includes('electr')) return 'Electrician';
  if (text.includes('dent') || text.includes('smile') || text.includes('implant')) return 'Dentist';
  if (text.includes('account') || text.includes('tax') || text.includes('bookkeep')) return 'Accountant';
  if (text.includes('build') || text.includes('construct') || text.includes('loft') || text.includes('extension')) return 'Builder';
  if (text.includes('carpent') || text.includes('joiner')) return 'Carpenter';
  if (text.includes('landscap') || text.includes('tree') || text.includes('garden')) return 'Landscaper';
  if (text.includes('clean')) return 'Cleaner';
  if (text.includes('paint') || text.includes('decorat')) return 'Decorator';
  return 'Tradesperson';
}

const validatedLeads = [];
const seenPhones = new Set();
const seenNames = new Set();

for (const item of items) {
  const place = item.json || {};
  const businessName = (place.title || place.name || '').trim();
  const rawPhone = (place.phoneNumber || place.phone || '').trim();
  const rawWebsite = (place.website || '').trim();
  const rating = Number(place.rating || 0);
  const reviewsCount = Number(place.ratingCount || place.user_ratings_total || 0);
  const address = (place.address || place.formatted_address || location).trim();
  const category = place.category || place.type || '';

  // Quality Gate 1: Require business name and contact phone
  if (!businessName || !rawPhone) continue;

  // Quality Gate 2: Exclude 0-review ghost listings if min_reviews set
  if (reviewsCount < minReviews) continue;

  // Quality Gate 3: Reject call centers & switchboards (0800, 0845, 0870, 0300, 0345)
  const cleanDigits = rawPhone.replace(/[^0-9]/g, '');
  if (
    cleanDigits.startsWith('0800') ||
    cleanDigits.startsWith('0808') ||
    cleanDigits.startsWith('0845') ||
    cleanDigits.startsWith('0870') ||
    cleanDigits.startsWith('0300') ||
    cleanDigits.startsWith('0345') ||
    cleanDigits.startsWith('44800') ||
    cleanDigits.startsWith('44845') ||
    cleanDigits.startsWith('44300')
  ) {
    continue;
  }

  // Quality Gate 4: Normalize phone to UK format (+44...)
  let formattedPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (formattedPhone.startsWith('0')) {
    formattedPhone = '+44' + formattedPhone.substring(1);
  } else if (!formattedPhone.startsWith('+44')) {
    formattedPhone = '+44' + formattedPhone.replace(/^\+/, '');
  }
  const digitsOnly = formattedPhone.replace(/[^0-9]/g, '');

  // Quality Gate 5: Deduplicate within current run
  const nameKey = businessName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seenPhones.has(digitsOnly) || seenNames.has(nameKey)) {
    continue;
  }
  seenPhones.add(digitsOnly);
  seenNames.add(nameKey);

  // Quality Gate 6: Online Presence Classification
  let hasWebsite = true;
  let classification = 'has_website';

  if (!rawWebsite || rawWebsite === '' || rawWebsite.toLowerCase() === 'none' || rawWebsite.toLowerCase() === 'null') {
    hasWebsite = false;
    classification = 'no_website';
  } else {
    const w = rawWebsite.toLowerCase();
    if (
      w.includes('facebook.com') ||
      w.includes('instagram.com') ||
      w.includes('yell.com') ||
      w.includes('checkatrade.com') ||
      w.includes('trustatrader.com') ||
      w.includes('bark.com') ||
      w.includes('mybuilder.com') ||
      w.includes('ratedpeople.com')
    ) {
      hasWebsite = false;
      classification = 'social_only';
    }
  }

  // Filter by user preference
  if (onlyNoWebsite && hasWebsite) {
    continue;
  }

  const isMobile = digitsOnly.startsWith('447');
  const channel = isMobile ? 'WhatsApp / SMS' : 'Landline / Direct Call';
  const waLink = isMobile ? `https://wa.me/${digitsOnly}?text=${encodeURIComponent('Hi 👋')}` : 'N/A';
  const trade = detectTrade(businessName, category, query);

  // Tailored cold outreach pitch
  const stage1Opener = 'Hi 👋';
  const stage2Pitch = !hasWebsite
    ? `Came across ${businessName} — had a look for your website, couldn't find one. Every day someone searches for a ${trade.toLowerCase()} near them in ${location}, sees you're not there, and books with whoever showed up instead. I build the digital storefront and speed-to-lead booking system before asking for anything. If it's not for you, no pressure at all.`
    : `Came across ${businessName} — saw your site, but noticed it isn't optimized for automated instant mobile quotes and speed-to-lead. We automate customer booking from enquiry to booked job.`;

  const followUp1 = `Hey — following up on ${businessName}. No pressure at all, just wanted to check if this landed and see where you're at.`;
  const followUpFinal = `Last one from me on this — if it's not a priority right now, that's completely fair. If it ever is, the offer stands, just say the word.`;

  // Supabase Payload for instant dashboard sync
  const supabasePayload = {
    name: 'Owner / Director',
    business_name: businessName,
    phone: formattedPhone,
    website: hasWebsite ? rawWebsite : (classification === 'social_only' ? rawWebsite : null),
    service_interested: 'Digital Storefront & Speed-to-Lead Automation',
    notes: `${address} · ★${rating} (${reviewsCount} reviews)`,
    status: 'New',
    source: 'google_maps_outreach',
    lead_type: 'local',
    local_business_niche: trade,
    outreach_category: classification,
    outreach_stage: 'uncontacted',
    whatsapp_direct_url: isMobile ? waLink : null,
    scraped_metadata: {
      address: address,
      rating: rating,
      reviews: reviewsCount,
      reviews_count: reviewsCount,
      rating_reviews: `${reviewsCount} (★${rating})`,
      trade: trade,
      channel: channel,
      stage_1_opener: stage1Opener,
      stage_2_pitch: stage2Pitch,
      follow_up_1: followUp1,
      follow_up_final: followUpFinal
    }
  };

  validatedLeads.push({
    json: {
      "Business Name": businessName,
      "Phone": formattedPhone,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Reviews": reviewsCount,
      "Rating": rating,
      "Website": rawWebsite || 'None',
      "Address": address,
      "Trade": trade,
      "Classification": classification,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Follow Up 1": followUp1,
      "Follow Up Final": followUpFinal,
      "Status": 'New',
      "supabase_payload": supabasePayload
    }
  });
}

return validatedLeads;
